```html
<!DOCTYPE html>
<html lang="zh-CN">
<style>

.dl-panel,
.dl-panel * {
  box-sizing: border-box;
}

.dl-panel {
  --魂核尺寸: 38px;
  --仪轨尺寸: 110px;
  --光束宽度: 24px;
  --主题主色: #00ffcc;
  --主题辅色: #0a192f;
  --主题高光: #ffffff;
  --主题底色: #06111e;
  --投影背景: rgba(0, 255, 204, 0.055);
  --实体背景: rgba(255, 255, 255, 0.075);
  --虚幻背景: rgba(255, 255, 255, 0.04);
  --投影圆角: 2px;
  --主题发光: 0 0 18px rgba(0, 255, 204, 0.46);
  --边线颜色: rgba(0, 255, 204, 0.32);
  --文字主色: #e9fffb;
  --文字弱色: #8ba9b7;
  --虚化强度: blur(8px);
  --字号倍率: 1;
  --阅读行高: 1.68;
  --魂环十年: #f4f7fb;
  --魂环百年: #ffd45a;
  --魂环千年: #b77cff;
  --魂环万年: #1b1b22;
  --魂环十万年: #ff3d53;
  --魂环神级: #ffdf70;
  --魂环当前色: var(--魂环千年);
  --魂环当前阴影: rgba(183, 124, 255, 0.42);
  position: relative;
  z-index: 0;
  margin: 10px 0;
  overflow: hidden;
  isolation: isolate;
  color: var(--文字主色);
  font-family: "Noto Serif SC", "Source Han Serif SC", "Microsoft YaHei", serif;
  font-size: calc(14px * var(--字号倍率));
  line-height: var(--阅读行高);
  border: 1px solid var(--边线颜色);
  border-radius: var(--投影圆角);
  background:
    radial-gradient(circle at 12% 18%, color-mix(in srgb, var(--主题主色) 22%, transparent), transparent 28%),
    repeating-linear-gradient(135deg, transparent 0 18px, color-mix(in srgb, var(--主题主色) 7%, transparent) 18px 19px),
    linear-gradient(145deg, color-mix(in srgb, var(--主题底色) 92%, transparent), color-mix(in srgb, #000 44%, var(--主题辅色)));
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.36), var(--主题发光);
}

.dl-panel[data-theme="炫世唐门"] {
  --主题主色: #00ffcc;
  --主题辅色: #0a192f;
  --主题高光: #ffffff;
  --主题底色: #06111e;
  --投影背景: rgba(0, 255, 204, 0.055);
  --实体背景: rgba(0, 255, 204, 0.085);
  --虚幻背景: rgba(0, 255, 204, 0.04);
  --投影圆角: 2px;
  --主题发光: 0 0 18px rgba(0, 255, 204, 0.46);
  --边线颜色: rgba(0, 255, 204, 0.34);
  --文字主色: #e9fffb;
  --文字弱色: #8ba9b7;
}

.dl-panel[data-theme="金龙王"] {
  --主题主色: #ff3300;
  --主题辅色: #1a0505;
  --主题高光: #ffd700;
  --主题底色: #140303;
  --投影背景: rgba(255, 51, 0, 0.07);
  --实体背景: rgba(255, 170, 0, 0.105);
  --虚幻背景: rgba(255, 51, 0, 0.05);
  --投影圆角: 0px;
  --主题发光: 0 0 22px rgba(255, 51, 0, 0.42);
  --边线颜色: rgba(255, 215, 0, 0.42);
  --文字主色: #fff0d7;
  --文字弱色: #c9966c;
  border-width: 2px;
}

.dl-panel[data-theme="银龙王"] {
  --主题主色: #e0eaff;
  --主题辅色: rgba(255, 255, 255, 0.12);
  --主题高光: #ffffff;
  --主题底色: rgba(10, 14, 24, 0.72);
  --投影背景: rgba(255, 255, 255, 0.1);
  --实体背景: rgba(255, 255, 255, 0.11);
  --虚幻背景: rgba(255, 255, 255, 0.055);
  --投影圆角: 20px;
  --主题发光: inset 0 0 18px rgba(255,255,255,0.12), 0 0 20px rgba(224, 234, 255, 0.28);
  --边线颜色: rgba(255, 255, 255, 0.3);
  --文字主色: #f7fbff;
  --文字弱色: #b8c7da;
  --虚化强度: blur(16px);
  backdrop-filter: var(--虚化强度);
}

.dl-panel[data-theme="幻海蝶舞"] {
  --主题主色: #00d2ff;
  --主题辅色: #ff7eb3;
  --主题高光: #ffd700;
  --主题底色: #062333;
  --投影背景: linear-gradient(135deg, rgba(0, 210, 255, 0.08), rgba(255, 126, 179, 0.08), rgba(255, 215, 0, 0.05));
  --实体背景: rgba(255, 255, 255, 0.11);
  --虚幻背景: rgba(0, 210, 255, 0.045);
  --投影圆角: 30px 40px 20px 40px;
  --主题发光: 0 0 15px rgba(0, 210, 255, 0.4), inset 0 0 20px rgba(255, 126, 179, 0.2);
  --边线颜色: rgba(255, 255, 255, 0.18);
  --文字主色: #f7feff;
  --文字弱色: #8ec9d7;
  --虚化强度: blur(12px) saturate(110%);
}

.dl-buffer {
  display: none;
}

.dl-main-stage {
  position: relative;
  z-index: 1;
  min-width: 0;
  padding: 12px;
}

.dl-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  margin-bottom: 11px;
}

.dl-title-wrap {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.dl-title-stack {
  min-width: 0;
}

.dl-sigil {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--边线颜色);
  border-radius: var(--投影圆角);
  color: var(--主题主色);
  background: color-mix(in srgb, var(--主题主色) 10%, transparent);
  box-shadow: var(--主题发光);
  font-family: "Cascadia Code", Consolas, monospace;
  font-weight: 900;
}

.dl-title {
  color: var(--文字主色);
  font-size: calc(15px * var(--字号倍率));
  font-weight: 900;
  letter-spacing: 0;
}

.dl-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}

.dl-stat-chip {
  display: inline-flex;
  align-items: center;
  min-height: 17px;
  padding: 0 6px;
  border: 1px solid color-mix(in srgb, var(--主题主色) 22%, rgba(255,255,255,0.14));
  border-radius: 999px;
  background: transparent;
  color: color-mix(in srgb, var(--文字弱色) 76%, var(--主题主色));
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(9px * var(--字号倍率));
  line-height: 1.2;
  white-space: nowrap;
}

.dl-anchor {
  max-width: 100%;
  margin-top: 2px;
  color: color-mix(in srgb, var(--文字弱色) 78%, transparent);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(10px * var(--字号倍率));
  font-weight: 400;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dl-controls {
  position: relative;
  justify-self: end;
  align-self: start;
  z-index: 5;
}

.dl-theme-button,
.dl-tool-button,
.dl-read-more,
.dl-accordion-head,
.dl-orbit-node {
  font: inherit;
}

.dl-controls summary {
  list-style: none;
}

.dl-controls summary::-webkit-details-marker {
  display: none;
}

.dl-theme-button,
.dl-tool-button {
  border: 1px solid var(--边线颜色);
  background: color-mix(in srgb, var(--主题主色) 10%, transparent);
  color: var(--文字主色);
  display: inline-grid;
  place-items: center;
  padding: 0;
  cursor: pointer;
  box-shadow: var(--主题发光);
  backdrop-filter: var(--虚化强度);
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease, opacity 0.16s ease;
}

.dl-tool-button {
  width: 30px;
  height: 30px;
  border-radius: 999px;
}

.dl-tool-menu {
  position: relative;
  z-index: 2;
}

.dl-theme-button {
  width: 18px;
  height: 18px;
  border-radius: 999px;
}

.dl-controls-popover {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  display: grid;
  grid-template-columns: repeat(4, 18px) repeat(2, 30px);
  align-items: center;
  gap: 7px;
  padding: 7px;
  border: 1px solid color-mix(in srgb, var(--主题主色) 28%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--主题底色) 74%, rgba(0, 0, 0, 0.32));
  box-shadow: 0 10px 24px rgba(0,0,0,0.28), var(--主题发光);
  backdrop-filter: var(--虚化强度);
  opacity: 0;
  transform: translateY(-4px) scale(0.98);
  transform-origin: top right;
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.dl-controls:not([open]) .dl-controls-popover {
  display: none;
}

.dl-controls[open] .dl-controls-popover {
  display: grid;
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.dl-controls[open] .dl-tool-menu {
  border-color: var(--主题主色);
  background: color-mix(in srgb, var(--主题主色) 16%, transparent);
}

.dl-theme-button:hover,
.dl-tool-button:hover {
  transform: translateY(-1px);
  border-color: var(--主题主色);
}

.dl-theme-button[data-theme-name="炫世唐门"] { background: linear-gradient(135deg, #0a192f, #00ffcc); }
.dl-theme-button[data-theme-name="金龙王"] { background: linear-gradient(135deg, #1a0505, #ff3300 58%, #ffd700); border-radius: 0; }
.dl-theme-button[data-theme-name="银龙王"] { background: linear-gradient(135deg, rgba(11,12,16,.6), #e0eaff); }
.dl-theme-button[data-theme-name="幻海蝶舞"] { background: linear-gradient(135deg, #00d2ff, #ff7eb3 55%, #ffd700); }
.dl-theme-button[aria-pressed="true"] { outline: 2px solid var(--主题主色); outline-offset: 2px; }

.dl-icon {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}


.dl-node-label,
.dl-node-count {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dl-node-count {
  color: var(--魂环神级);
  font-size: calc(9px * var(--字号倍率));
  opacity: 0.86;
}

.dl-node-lamp {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: rgba(244, 247, 251, 0.58);
  box-shadow: 0 0 7px rgba(244, 247, 251, 0.24);
}

.dl-node-lamp.dl-route-hit {
  background: var(--魂环千年);
  box-shadow: 0 0 12px rgba(183, 124, 255, 0.86);
  animation: dl-pulse 1.5s ease-in-out infinite;
}

.dl-node-lamp.dl-route-idle {
  background: rgba(244, 247, 251, 0.55);
}

.dl-holo-layout {
  display: grid;
  grid-template-columns: 110px 24px minmax(0, 1fr);
  gap: 0;
  align-items: center;
  min-width: 0;
}

.dl-orbital-hub {
  position: relative;
  width: var(--仪轨尺寸);
  height: var(--仪轨尺寸);
  justify-self: center;
  flex: 0 0 auto;
  opacity: 0;
  animation: dl-deploy-hub 0.42s ease-out forwards;
}

.dl-orbit-ring,
.dl-orbit-ring::before,
.dl-orbit-ring::after,
.dl-orbit-radar,
.dl-core,
.dl-orbit-node {
  position: absolute;
}

.dl-orbit-ring {
  inset: 7px;
  border-radius: 999px;
  border: 1px dashed color-mix(in srgb, var(--主题主色) 38%, transparent);
  box-shadow: inset 0 0 12px color-mix(in srgb, var(--主题主色) 14%, transparent), 0 0 16px color-mix(in srgb, var(--主题主色) 18%, transparent);
  animation: dl-spin 30s linear infinite;
}

.dl-orbit-ring::before,
.dl-orbit-ring::after {
  content: "";
  inset: 14px;
  border-radius: inherit;
  border: 1px solid color-mix(in srgb, var(--主题高光) 16%, transparent);
}

.dl-orbit-ring::after {
  inset: 26px;
  border-style: dotted;
  opacity: 0.55;
}

.dl-orbit-radar {
  inset: 12px;
  border-radius: 999px;
  background: conic-gradient(from 0deg, color-mix(in srgb, var(--主题主色) 32%, transparent), transparent 32deg, transparent 360deg);
  opacity: 0.38;
  animation: dl-spin 6s linear infinite;
  pointer-events: none;
}

.dl-core {
  top: 50%;
  left: 50%;
  width: var(--魂核尺寸);
  height: var(--魂核尺寸);
  display: grid;
  place-items: center;
  border-radius: 999px;
  color: color-mix(in srgb, var(--主题底色) 70%, #000);
  background:
    radial-gradient(circle at 32% 28%, #fff 0 8%, color-mix(in srgb, var(--主题高光) 86%, #fff) 9% 18%, var(--主题主色) 42%, color-mix(in srgb, var(--主题辅色) 72%, #000) 100%);
  box-shadow: 0 0 14px var(--主题主色), 0 0 26px color-mix(in srgb, var(--主题主色) 36%, transparent);
  font-family: "Cascadia Code", Consolas, monospace;
  font-size: 10px;
  font-weight: 900;
  transform: translate(-50%, -50%) scale(0.96);
  animation: dl-core-breathe 3.8s ease-in-out infinite;
}

.dl-orbit-node {
  width: 44px;
  min-height: 24px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 3px;
  padding: 3px 5px;
  border: 1px solid color-mix(in srgb, var(--主题主色) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--主题底色) 58%, transparent);
  color: var(--文字主色);
  cursor: pointer;
  box-shadow: 0 0 10px color-mix(in srgb, var(--主题主色) 16%, transparent);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(10px * var(--字号倍率));
  font-weight: 800;
  line-height: 1.05;
  opacity: 0;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, background 0.18s ease;
  animation: dl-node-in 0.32s ease-out forwards;
}

.dl-orbit-node:hover,
.dl-orbit-node[data-active="true"] {
  border-color: var(--主题主色);
  background: color-mix(in srgb, var(--主题主色) 10%, transparent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--主题主色) 36%, transparent);
}

.dl-orbit-node:hover {
  transform: scale(1.12);
}

.dl-node-story { top: -1px; left: 50%; transform: translateX(-50%); animation-delay: 0.12s; }
.dl-node-npc { left: -3px; top: 34%; transform: translateY(-50%); animation-delay: 0.18s; }
.dl-node-review { right: -3px; top: 34%; transform: translateY(-50%); animation-delay: 0.24s; }
.dl-node-recall { left: 6px; bottom: 26px; animation-delay: 0.3s; }
.dl-node-deviation { right: 6px; bottom: 26px; animation-delay: 0.36s; }
.dl-node-backstage { bottom: -1px; left: 50%; transform: translateX(-50%); animation-delay: 0.42s; }
.dl-node-story:hover,
.dl-node-story[data-active="true"],
.dl-node-backstage:hover,
.dl-node-backstage[data-active="true"] { transform: translateX(-50%) scale(1.08); }
.dl-node-npc:hover,
.dl-node-npc[data-active="true"],
.dl-node-review:hover,
.dl-node-review[data-active="true"] { transform: translateY(-50%) scale(1.08); }
.dl-node-recall:hover,
.dl-node-recall[data-active="true"],
.dl-node-deviation:hover,
.dl-node-deviation[data-active="true"] { transform: scale(1.08); }

.dl-beam {
  position: relative;
  z-index: 1;
  height: 2px;
  width: 100%;
  margin: 0;
  background: linear-gradient(90deg, transparent, var(--主题主色), color-mix(in srgb, var(--主题主色) 36%, transparent), transparent);
  border-radius: 999px;
  filter: drop-shadow(0 0 5px var(--主题主色));
  opacity: 0;
  animation: dl-beam-fire 0.42s ease-out 0.42s forwards;
}

.dl-beam::after {
  content: "";
  position: absolute;
  inset: -2px 0;
  background: linear-gradient(90deg, transparent, var(--主题高光), transparent);
  width: 26%;
  animation: dl-data-stream 1.6s linear infinite;
}

.dl-projection-screen {
  position: relative;
  min-width: 0;
  min-height: 260px;
  padding: 14px;
  border: 1px solid var(--边线颜色);
  border-radius: var(--投影圆角);
  background: var(--投影背景);
  box-shadow: var(--主题发光), inset 0 0 22px color-mix(in srgb, var(--主题主色) 10%, transparent);
  backdrop-filter: var(--虚化强度);
  overflow: hidden;
  opacity: 0;
  transform-origin: left center;
  animation: dl-screen-deploy 0.38s ease-out 0.5s forwards;
}

.dl-projection-screen::before,
.dl-projection-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.dl-projection-screen::before {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 38%, transparent), transparent 22%),
    radial-gradient(circle at 95% 12%, color-mix(in srgb, var(--主题高光) 18%, transparent), transparent 22%);
  opacity: 0.52;
}

.dl-projection-screen::after {
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0, 0, 0, 0.14) 3px 4px);
  mix-blend-mode: multiply;
  opacity: 0.38;
}

.dl-panel[data-switching="true"] .dl-projection-screen {
  animation: dl-hologram-flicker 0.2s ease-out;
}

.dl-projection-head,
.dl-scene-context,
.dl-profiles,
.dl-story-flow,
.dl-data-flow,
.dl-empty {
  position: relative;
  z-index: 1;
}

.dl-projection-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid color-mix(in srgb, var(--主题主色) 25%, transparent);
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
}

.dl-view-title {
  color: var(--主题主色);
  font-size: calc(12px * var(--字号倍率));
  font-weight: 900;
}

.dl-view-state {
  color: var(--文字弱色);
  font-size: calc(10px * var(--字号倍率));
  font-weight: 800;
}

.dl-scene-context {
  display: grid;
  gap: 7px;
  min-width: 0;
  margin: 0 0 11px;
  transition: opacity 0.18s ease, filter 0.18s ease, transform 0.18s ease;
}

.dl-scene-description {
  min-width: 0;
  padding: 8px 11px 9px 13px;
  border-left: 1px solid color-mix(in srgb, var(--魂环当前色) 42%, transparent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--魂环当前色) 8%, transparent), transparent 76%);
  color: color-mix(in srgb, var(--文字主色) 58%, var(--文字弱色));
  font-style: italic;
  line-height: 1.66;
  text-shadow: 0 0 8px color-mix(in srgb, var(--魂环当前色) 10%, transparent);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.dl-scene-description:empty {
  display: none;
}

.dl-scene-description p {
  margin: 0;
}

.dl-scene-description p + p {
  margin-top: 6px;
}

.dl-scene-bar {
  display: flex;
  flex-wrap: nowrap;
  gap: 5px;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  margin: 0;
  padding: 0 0 2px;
  scrollbar-width: thin;
}

.dl-scene-chip,
.dl-ring-chip {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  max-width: none;
  padding: 1px 8px;
  border: 1px solid color-mix(in srgb, var(--魂环当前色) 30%, rgba(255, 255, 255, 0.14));
  border-radius: 999px;
  background: transparent;
  color: color-mix(in srgb, var(--文字弱色) 74%, var(--魂环当前色));
  font-family: "Cascadia Code", Consolas, "Microsoft YaHei", sans-serif;
  font-size: calc(10px * var(--字号倍率));
  font-weight: 400;
  line-height: 1.35;
  white-space: nowrap;
}

.dl-profiles {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 1px 0 8px;
  scrollbar-width: thin;
  transition: opacity 0.18s ease, filter 0.18s ease, transform 0.18s ease;
}

.dl-profile-card {
  --魂环当前色: var(--魂环百年);
  flex: 0 0 min(230px, 78%);
  border: 1px solid color-mix(in srgb, var(--魂环当前色) 50%, transparent);
  border-left: 4px solid var(--魂环当前色);
  border-radius: var(--投影圆角);
  background: var(--实体背景);
  box-shadow: 2px 4px 10px rgba(0,0,0,0.3), 0 0 10px var(--魂环当前阴影);
  padding: 9px;
  cursor: pointer;
}

.dl-profile-head {
  display: flex;
  gap: 8px;
  align-items: center;
  min-width: 0;
}

.dl-avatar {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: var(--投影圆角);
  border: 1px solid color-mix(in srgb, var(--魂环当前色) 46%, transparent);
  color: var(--魂环当前色);
  background: color-mix(in srgb, var(--魂环当前色) 10%, transparent);
  font-weight: 900;
}

.dl-profile-name {
  color: var(--魂环当前色);
  font-weight: 900;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dl-profile-summary {
  color: var(--文字弱色);
  font-size: calc(11px * var(--字号倍率));
  margin-top: 2px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dl-profile-detail {
  display: none;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--边线颜色);
}

.dl-profile-card[data-open="true"] .dl-profile-detail {
  display: block;
}

.dl-story-flow {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  overflow: visible;
  padding-right: 0;
  transition: opacity 0.18s ease, filter 0.18s ease, transform 0.18s ease;
}

.dl-data-flow {
  display: none;
  min-width: 0;
  overflow: visible;
  padding-right: 0;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
}

.dl-panel:not([data-view="正文"]) .dl-scene-context,
.dl-panel:not([data-view="NPC"]) .dl-profiles,
.dl-panel:not([data-view="正文"]) .dl-story-flow {
  display: none;
}

.dl-panel[data-view="NPC"] .dl-profiles:not(.dl-hidden) {
  display: flex;
}

.dl-panel[data-view="正文"] .dl-story-flow {
  display: flex;
}

.dl-panel[data-view="推演"] [data-role="推演流"],
.dl-panel[data-view="召回"] [data-role="召回流"],
.dl-panel[data-view="偏差"] [data-role="偏差流"],
.dl-panel[data-view="后台"] [data-role="后台流"] {
  display: grid;
  animation: dl-hologram-materialize 0.28s ease-out;
}

.dl-card-act {
  --魂环当前色: var(--魂环千年);
  position: relative;
  border: 0;
  border-left: 2px solid color-mix(in srgb, var(--魂环当前色) 58%, transparent);
  border-radius: 0;
  background: transparent;
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--魂环当前色) 18%, transparent);
  padding: 5px 0 5px 12px;
  font-weight: 400;
  min-width: 0;
}

.dl-card-title,
.dl-card-name {
  color: var(--魂环当前色);
  font-weight: 900;
  margin-bottom: 7px;
  text-shadow: 0 0 8px var(--魂环当前阴影);
}

.dl-fields {
  display: grid;
  gap: 2px;
}

.dl-field-row {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  margin-bottom: 7px;
}

.dl-field-name {
  color: color-mix(in srgb, var(--魂环当前色) 30%, transparent);
  font-family: "Cascadia Code", Consolas, monospace;
  font-size: calc(10px * var(--字号倍率));
  font-weight: 400;
  line-height: 1.65;
  text-align: right;
  text-transform: lowercase;
}

.dl-field-value {
  min-width: 0;
  color: color-mix(in srgb, var(--文字主色) 70%, var(--文字弱色));
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  line-height: 1.68;
}

.dl-action-text {
  color: color-mix(in srgb, var(--文字主色) 56%, var(--文字弱色));
}

.dl-dialogue {
  color: color-mix(in srgb, #fff 82%, var(--魂环当前色));
  font-weight: 700;
  text-shadow: 0 0 7px color-mix(in srgb, var(--魂环当前色) 28%, transparent);
}

.dl-card-inner {
  --魂环当前色: var(--魂环百年);
  margin: 3px 0 0 18px;
  padding: 8px 12px 10px;
  border: 0;
  border-left: 2px solid color-mix(in srgb, var(--魂环当前色) 48%, transparent);
  border-radius: 18px 0 0 18px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--魂环当前色) 10%, transparent), transparent 76%);
  color: color-mix(in srgb, var(--文字主色) 68%, var(--魂环当前色));
  backdrop-filter: blur(4px);
  font-style: italic;
  box-shadow: inset 10px 0 18px color-mix(in srgb, var(--魂环当前色) 8%, transparent);
  text-shadow: 0 0 5px color-mix(in srgb, var(--魂环当前色) 20%, transparent);
}

.dl-card-act > .dl-card-inner {
  margin-top: 7px;
  margin-bottom: -4px;
}

.dl-stage-text {
  --魂环当前色: var(--魂环十年);
  position: relative;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--投影圆角);
  background: linear-gradient(90deg, color-mix(in srgb, var(--魂环当前色) 7%, transparent), transparent 76%);
  color: color-mix(in srgb, var(--文字主色) 72%, var(--文字弱色));
  backdrop-filter: blur(4px);
  font-style: italic;
}

.dl-stage-text[data-collapsed="true"] .dl-stage-body {
  max-height: 200px;
  overflow: hidden;
  mask-image: linear-gradient(180deg, #000 72%, transparent);
}

.dl-read-more {
  margin-top: 7px;
  border: 1px solid color-mix(in srgb, var(--魂环当前色) 44%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--魂环当前色) 10%, transparent);
  color: color-mix(in srgb, var(--文字主色) 70%, var(--魂环当前色));
  padding: 3px 10px;
  cursor: pointer;
  font-size: calc(11px * var(--字号倍率));
}

.dl-review-section {
  min-width: 0;
  max-width: 100%;
}

.dl-review-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--主题主色);
  font-size: calc(12px * var(--字号倍率));
  font-weight: 900;
  margin-bottom: 8px;
}

.dl-review-section-title::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, var(--边线颜色), transparent);
}

.dl-route-box,
.dl-world-card,
.dl-step-item,
.dl-accordion-item {
  border: 0;
  border-left: 2px solid color-mix(in srgb, var(--魂环当前色) 62%, transparent);
  border-radius: 0;
  background: transparent;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  padding: 6px 0 6px 12px;
  margin-bottom: 8px;
}

.dl-route-box[data-route-hit="true"] {
  --魂环当前色: var(--魂环十万年);
  border-left-color: var(--魂环当前色);
  box-shadow: inset 2px 0 0 color-mix(in srgb, var(--魂环当前色) 42%, transparent), 0 0 10px color-mix(in srgb, var(--魂环当前色) 18%, transparent);
}

.dl-review-steps {
  position: relative;
  display: grid;
  gap: 8px;
}

.dl-review-steps::before {
  content: "";
  position: absolute;
  left: 0;
  top: 2px;
  bottom: 8px;
  width: 1px;
  background: color-mix(in srgb, var(--魂环当前色) 28%, transparent);
}

.dl-step-item {
  position: relative;
  margin-left: 0;
  padding: 7px 0 7px 14px;
}

.dl-step-item::before {
  content: "";
  position: absolute;
  left: -5px;
  top: 14px;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--魂环当前色);
  box-shadow: 0 0 9px var(--魂环当前阴影);
}

.dl-step-title {
  color: var(--魂环当前色);
  font-weight: 900;
  margin-bottom: 4px;
}

.dl-accordion-head {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  color: var(--魂环当前色);
  padding: 0;
  cursor: pointer;
  text-align: left;
  font-family: "Cascadia Code", Consolas, monospace;
  font-weight: 400;
}

.dl-accordion-head::before {
  content: "> ";
  opacity: 0.5;
}

.dl-accordion-body {
  display: none;
  margin-top: 7px;
  padding: 5px 0 0;
  color: color-mix(in srgb, var(--文字主色) 72%, var(--文字弱色));
  font-family: "Cascadia Code", Consolas, monospace;
  font-size: calc(12px * var(--字号倍率));
  opacity: 0.82;
}

.dl-accordion-item[data-open="true"] .dl-accordion-body {
  display: block;
}

.dl-text-block {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.dl-empty {
  color: var(--文字弱色);
  padding: 10px 0;
  font-size: calc(12px * var(--字号倍率));
}

.dl-hidden {
  display: none;
}

.dl-ring-white {
  --魂环当前色: var(--魂环十年);
  --魂环当前阴影: rgba(244, 247, 251, 0.25);
}

.dl-ring-yellow {
  --魂环当前色: var(--魂环百年);
  --魂环当前阴影: rgba(255, 212, 90, 0.38);
}

.dl-ring-purple {
  --魂环当前色: var(--魂环千年);
  --魂环当前阴影: rgba(183, 124, 255, 0.42);
}

.dl-ring-black {
  --魂环当前色: var(--魂环万年);
  --魂环当前阴影: rgba(255, 83, 99, 0.32);
}

.dl-ring-red {
  --魂环当前色: var(--魂环十万年);
  --魂环当前阴影: rgba(255, 61, 83, 0.48);
}

.dl-ring-gold {
  --魂环当前色: var(--魂环神级);
  --魂环当前阴影: rgba(255, 223, 112, 0.55);
}

.dl-panel[data-theme="炫世唐门"] .dl-projection-screen {
  clip-path: polygon(15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%, 0 15px);
}

.dl-panel[data-theme="炫世唐门"] .dl-projection-screen {
  border-color: transparent;
}

.dl-panel[data-theme="炫世唐门"] .dl-projection-screen::before {
  background:
    linear-gradient(90deg, var(--主题主色) 0 2px, transparent 2px) left top / 46px 2px no-repeat,
    linear-gradient(180deg, var(--主题主色) 0 2px, transparent 2px) left top / 2px 46px no-repeat,
    linear-gradient(270deg, var(--主题主色) 0 2px, transparent 2px) right bottom / 46px 2px no-repeat,
    linear-gradient(0deg, var(--主题主色) 0 2px, transparent 2px) right bottom / 2px 46px no-repeat,
    linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 30%, transparent), transparent 28%);
  background-repeat: no-repeat;
}

.dl-panel[data-theme="炫世唐门"] .dl-orbit-node[data-active="true"] {
  background:
    repeating-linear-gradient(90deg, transparent 0 8px, rgba(0, 255, 204, 0.18) 8px 10px),
    color-mix(in srgb, var(--主题主色) 16%, transparent);
  animation: dl-scanline 1.4s linear infinite;
}

.dl-panel[data-theme="金龙王"] .dl-core {
  border-radius: 8px;
  transform: translate(-50%, -50%) rotate(45deg) scale(0.94);
  animation: dl-dragon-heart 1.65s ease-in-out infinite;
}

.dl-panel[data-theme="金龙王"] .dl-core span {
  transform: rotate(-45deg);
}

.dl-panel[data-theme="金龙王"] .dl-beam {
  height: 4px;
  background: linear-gradient(90deg, #ffd700, #ff3300, transparent);
  animation: dl-beam-fire 0.42s ease-out 0.42s forwards, dl-dragon-flicker 0.8s steps(2, end) infinite;
}

.dl-panel[data-theme="金龙王"] .dl-projection-screen {
  border-width: 2px;
  background-image:
    radial-gradient(circle at 10% 10%, rgba(255, 170, 0, 0.14), transparent 24%),
    repeating-linear-gradient(135deg, rgba(255,255,255,0.04) 0 1px, transparent 1px 7px);
}

.dl-panel[data-theme="金龙王"][data-switching="true"] .dl-projection-screen {
  animation: dl-glitch-switch 0.2s steps(2, end);
}

.dl-panel[data-theme="银龙王"] .dl-orbit-ring {
  border-color: rgba(255,255,255,0.35);
  box-shadow: 0 0 0 4px rgba(224,234,255,0.08), 0 0 0 8px rgba(255,255,255,0.045), 0 0 30px rgba(224,234,255,0.26);
}

.dl-panel[data-theme="银龙王"] .dl-projection-screen,
.dl-panel[data-theme="银龙王"] .dl-card-act,
.dl-panel[data-theme="银龙王"] .dl-profile-card {
  border-color: rgba(255,255,255,0.3);
  box-shadow: inset 0 0 15px rgba(255,255,255,0.1), var(--主题发光);
}

.dl-panel[data-theme="银龙王"] .dl-orbit-node:hover {
  box-shadow: 0 0 10px #fff, 0 0 24px rgba(224,234,255,0.55);
}

.dl-panel[data-theme="幻海蝶舞"] .dl-projection-screen {
  border-color: transparent;
  background:
    radial-gradient(circle at 18% 24%, rgba(255,255,255,0.22), transparent 18%),
    var(--投影背景);
  box-shadow: var(--主题发光), 0 0 30px rgba(255, 126, 179, 0.22);
}

.dl-panel[data-theme="幻海蝶舞"] .dl-projection-screen::before {
  background:
    radial-gradient(ellipse at 20% 30%, rgba(255,255,255,0.16), transparent 18%),
    radial-gradient(ellipse at 70% 60%, rgba(0,210,255,0.18), transparent 22%),
    linear-gradient(115deg, transparent 0 22%, rgba(255,255,255,0.09) 24%, transparent 30%, rgba(255,215,0,0.06) 45%, transparent 52%);
  background-size: 160% 160%;
  opacity: 0.86;
  animation: dl-water-caustics 8s ease-in-out infinite;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-projection-screen::after {
  display: none;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-ring {
  border: 0;
  box-shadow:
    0 0 0 2px rgba(0, 210, 255, 0.26),
    0 0 0 10px rgba(255, 126, 179, 0.09),
    0 0 0 18px rgba(255, 215, 0, 0.055),
    0 0 34px rgba(0, 210, 255, 0.34);
}

.dl-panel[data-theme="幻海蝶舞"] .dl-core {
  background: radial-gradient(circle at 30% 30%, #ffffff 0 12%, #00d2ff 54%, #ff7eb3 100%);
  box-shadow: 0 0 20px #00d2ff, 0 0 40px #ffd700, inset 0 0 18px rgba(255,255,255,0.5);
  animation: dl-core-levitate 4s ease-in-out infinite;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-beam {
  height: 3px;
  background: linear-gradient(90deg, #00d2ff, #ff7eb3, rgba(255, 215, 0, 0.35), transparent);
  border-radius: 3px;
  filter: drop-shadow(0 0 5px #ff7eb3);
}

.dl-panel[data-theme="幻海蝶舞"] .dl-beam::after {
  inset: -4px 0;
  width: 100%;
  background: repeating-linear-gradient(90deg, transparent 0 7px, #fff 7px 8px, transparent 8px 14px);
  opacity: 0.5;
  animation: dl-butterfly-dust 2s linear infinite;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-node::after {
  content: "";
  position: absolute;
  inset: -6px;
  border: 1px solid rgba(255, 126, 179, 0.45);
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-node:hover::after,
.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-node[data-active="true"]::after {
  animation: dl-ripple-out 0.9s ease-out;
}

.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-node:hover,
.dl-panel[data-theme="幻海蝶舞"] .dl-orbit-node[data-active="true"] {
  animation: dl-soft-bounce 1.6s ease-in-out infinite;
}

.dl-panel[data-density="紧凑"] {
  --阅读行高: 1.48;
}

.dl-panel[data-density="紧凑"] .dl-main-stage {
  padding: 9px;
}

.dl-panel[data-density="紧凑"] .dl-projection-screen,
.dl-panel[data-density="紧凑"] .dl-card-act,
.dl-panel[data-density="紧凑"] .dl-profile-card,
.dl-panel[data-density="紧凑"] .dl-card-inner,
.dl-panel[data-density="紧凑"] .dl-stage-text {
  padding-top: 8px;
  padding-bottom: 8px;
}

@keyframes dl-hologram-materialize {
  from { opacity: 0; filter: blur(6px); transform: translateY(5px) scale(0.985); }
  to { opacity: 1; filter: blur(0); transform: translateY(0) scale(1); }
}

@keyframes dl-spin {
  to { transform: rotate(360deg); }
}

@keyframes dl-core-breathe {
  0%, 100% { transform: translate(-50%, -50%) scale(0.95); opacity: 0.86; }
  50% { transform: translate(-50%, -50%) scale(1.05); opacity: 1; }
}

@keyframes dl-deploy-hub {
  from { opacity: 0; transform: scale(0.82); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes dl-node-in {
  from { opacity: 0; filter: blur(5px); }
  to { opacity: 1; filter: blur(0); }
}

@keyframes dl-beam-fire {
  from { opacity: 0; transform: scaleX(0); }
  to { opacity: 1; transform: scaleX(1); }
}

@keyframes dl-data-stream {
  from { transform: translateX(-80%); opacity: 0; }
  25%, 70% { opacity: 0.9; }
  to { transform: translateX(260%); opacity: 0; }
}

@keyframes dl-screen-deploy {
  from { opacity: 0; transform: scaleX(0.04); }
  to { opacity: 1; transform: scaleX(1); }
}

@keyframes dl-hologram-flicker {
  0% { opacity: 1; transform: scaleX(1); filter: none; }
  45% { opacity: 0.35; transform: scaleX(1.025); filter: blur(1px); }
  100% { opacity: 1; transform: scaleX(1); filter: none; }
}

@keyframes dl-glitch-switch {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(2px) skewX(1.5deg); }
  50% { transform: translateX(-2px) skewX(-1deg); }
  75% { transform: translateX(1px); }
}

@keyframes dl-scanline {
  from { background-position: 0 0; }
  to { background-position: 48px 0; }
}

@keyframes dl-pulse {
  0%, 100% { opacity: 0.72; transform: scale(0.94); }
  50% { opacity: 1; transform: scale(1.08); }
}

@keyframes dl-dragon-heart {
  0%, 100% { transform: translate(-50%, -50%) rotate(45deg) scale(0.9); }
  38% { transform: translate(-50%, -50%) rotate(45deg) scale(1.08); }
  50% { transform: translate(-50%, -50%) rotate(45deg) scale(0.96); }
}

@keyframes dl-dragon-flicker {
  0%, 100% { opacity: 0.88; }
  50% { opacity: 1; filter: drop-shadow(0 0 9px #ff3300); }
}

@keyframes dl-water-caustics {
  0%, 100% { background-position: 0% 45%; }
  50% { background-position: 100% 55%; }
}

@keyframes dl-core-levitate {
  0%, 100% { transform: translate(-50%, -50%) translateY(0) scale(0.98); }
  50% { transform: translate(-50%, -50%) translateY(-6px) scale(1.03); }
}

@keyframes dl-butterfly-dust {
  0% { transform: translateX(-18px); opacity: 0; }
  50% { opacity: 0.8; }
  100% { transform: translateX(50px); opacity: 0; }
}

@keyframes dl-ripple-out {
  0% { opacity: 0.8; transform: scale(0.72); }
  100% { opacity: 0; transform: scale(1.55); }
}

@keyframes dl-soft-bounce {
  0%, 100% { box-shadow: 0 0 16px rgba(0, 210, 255, 0.32); }
  50% { box-shadow: 0 0 24px rgba(255, 126, 179, 0.42); }
}

@media (max-width: 760px) {
  .dl-header {
    grid-template-columns: 1fr;
  }

  .dl-controls {
    justify-self: start;
  }

  .dl-controls-popover {
    left: 0;
    right: auto;
    transform-origin: top left;
  }

  .dl-holo-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 7px;
  }

  .dl-orbital-hub {
    width: min(220px, 100%);
    height: 98px;
    overflow: hidden;
  }

  .dl-orbit-ring {
    inset: 8px 38px -78px;
  }

  .dl-orbit-ring::before {
    inset: 14px;
  }

  .dl-orbit-ring::after,
  .dl-orbit-radar {
    display: none;
  }

  .dl-core {
    top: 79%;
  }

  .dl-orbit-node {
    width: 44px;
    padding-inline: 5px;
  }

  .dl-node-story { top: 2px; left: 4%; transform: none; }
  .dl-node-npc { top: 2px; left: 34%; transform: none; }
  .dl-node-review { top: 2px; right: 4%; transform: none; }
  .dl-node-recall { top: 31px; left: 10%; transform: none; }
  .dl-node-deviation { top: 31px; right: 10%; transform: none; }
  .dl-node-backstage { top: 68px; bottom: auto; left: 50%; transform: translateX(-50%); }
  .dl-node-story:hover,
  .dl-node-story[data-active="true"],
  .dl-node-npc:hover,
