  function 内心键(事件) {
    return (取属性(事件, 'name') || '') + '\n' + 清理文本(事件.内容);
  }

  function 解析裸舞台字段(文本) {
    const 清理 = 清理文本(文本);
    const 位置 = 找分隔位置(清理);
    if (位置 < 0) return null;
    const 键 = 清理.slice(0, 位置).trim().toLowerCase();
    const 值 = 清理.slice(位置 + 1).trim();
    if (键 === 'interplay') return { 标签: 'interplay', 内容: 值 };
    return null;
  }

  function 生成正文(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="正文流"]');
    清空(容器);
    const 已用内心 = new Set();
    const 内心们 = 数据.npc_inner.map(function (项) { return { 标签: 'npc_inner', 属性: 项.属性, 内容: 清理文本(项.内容), 起点: 项.起点, 终点: 项.终点 }; });
    let 数量 = 0;

    function 取匹配内心(名称) {
      for (const 内心 of 内心们) {
        const 键 = 内心键(内心);
        if (!已用内心.has(键) && 取属性(内心, 'name') === 名称) return 内心;
      }
      return null;
    }

    for (const 事件 of 数据.舞台事件) {
      if (事件.标签 === 'act') {
        const 卡 = 生成行动卡(事件);
        const 内心 = 取匹配内心(取属性(事件, 'name'));
        if (内心) {
          卡.appendChild(生成内心卡(内心));
          已用内心.add(内心键(内心));
          数量 += 1;
        }
        容器.appendChild(卡);
        数量 += 1;
      } else if (事件.标签 === 'npc_inner') {
        const 键 = 内心键(事件);
        if (!已用内心.has(键)) {
          容器.appendChild(生成内心卡(事件));
          已用内心.add(键);
          数量 += 1;
        }
      } else if (事件.标签 === 'interplay') {
        容器.appendChild(生成旁白卡(事件.内容));
        数量 += 1;
      } else if (!是空内容(事件.内容)) {
        const 裸字段 = 解析裸舞台字段(事件.内容);
        容器.appendChild(生成旁白卡(裸字段 ? 裸字段.内容 : 事件.内容));
        数量 += 1;
      }
    }

    for (const 内心 of 内心们) {
      const 键 = 内心键(内心);
      if (已用内心.has(键)) continue;
      容器.appendChild(生成内心卡(内心));
      已用内心.add(键);
      数量 += 1;
    }

    return 数量;
  }

  function 分解步骤(内容) {
    const 文本 = 清理文本(内容);
    if (!文本) return [];
    const 标题正则 = /^\s*(step\s*\d+[^：:\n]*(?:[：:]|）)?|步骤\s*\d+[^：:\n]*(?:[：:]|）)?|【结果】)\s*/i;
    const 步骤 = [];
    const 前置 = [];
    let 当前 = null;

    function 推入当前() {
      if (!当前) return;
      const 正文 = 清理文本(当前.内容.join('\n'));
      if (当前.标题 || 正文) 步骤.push({ 标题: 当前.标题, 内容: 正文 });
      当前 = null;
    }

    for (const 原行 of 文本.split('\n')) {
      const 行 = 原行.trim();
      if (!行) continue;
      const 匹配 = 行.match(标题正则);
      if (匹配) {
        if (!当前 && 前置.length) {
          步骤.push({ 标题: '', 内容: 清理文本(前置.join('\n')) });
          前置.length = 0;
        }
        推入当前();
        const 标题 = 匹配[1].replace(/[：:]$/, '').trim();
        const 剩余 = 行.slice(匹配[0].length).trim();
        当前 = { 标题: 标题, 内容: [] };
        if (剩余) 当前.内容.push(剩余);
      } else if (当前) {
        当前.内容.push(行);
      } else {
        前置.push(行);
      }
    }
    推入当前();
    if (前置.length) 步骤.push({ 标题: '', 内容: 清理文本(前置.join('\n')) });
    return 步骤.length ? 步骤 : [{ 标题: '', 内容: 文本 }];
  }

  function 生成步骤列(标题, 文本们, 默认类) {
    const 列 = 新建('div', 'dl-review-steps');
    let 数量 = 0;
    for (const 文本 of 文本们) {
      for (const 步骤 of 分解步骤(文本)) {
        const 卡 = 应用魂环(新建('div', 'dl-step-item'), 取魂环类(标题 + '\n' + 步骤.标题 + '\n' + 步骤.内容, 默认类 || 'dl-ring-yellow'));
        卡.appendChild(新建('div', 'dl-step-title', 步骤.标题 ? 标题 + ' · ' + 步骤.标题 : 标题));
        if (!是空内容(步骤.内容)) 卡.appendChild(新建('div', 'dl-text-block', 清理文本(步骤.内容)));
        列.appendChild(卡);
        数量 += 1;
      }
    }
    return { 节点: 列, 数量: 数量 };
  }

  function 拆账本条目(内容) {
    const 文本 = 清理文本(内容);
    if (!文本) return [];
    const 空段 = 文本.split(/\n\s*\n+/).map(function (段) { return 清理文本(段); }).filter(Boolean);
    if (空段.length > 1) return 空段;
    const 行们 = 切行(文本);
    const 可分行数 = 行们.filter(function (行) { return /^(?:AM\d+|DV\d+|Day\s*\d+|[-·*]\s+|\[[^\]]+\]|【[^】]+】)/i.test(行); }).length;
    if (行们.length > 2 && 可分行数 >= 2) return 行们;
    return [文本];
  }

  function 生成折叠项(标题, 内容, 默认类) {
    const 文本 = 清理文本(内容);
    const 项 = 应用魂环(新建('div', 'dl-accordion-item'), 取魂环类(标题 + '\n' + 文本, 默认类 || 'dl-ring-yellow'));
    项.dataset.open = 'false';
    const 头 = 新建('button', 'dl-accordion-head');
    头.type = 'button';
    头.appendChild(新建('span', 'dl-accordion-title', 标题));
    头.appendChild(新建('span', 'dl-ring-chip', 文本.length + '字'));
    const 体 = 新建('div', 'dl-accordion-body');
    体.appendChild(生成字段组(文本, false));
    头.addEventListener('click', function () {
      项.dataset.open = 项.dataset.open === 'true' ? 'false' : 'true';
    });
    项.append(头, 体);
    return 项;
  }

  function 渲染路由(面板, 数据) {
