    容器.appendChild(新建('div', 'dl-review-section-title', '模块路由'));
    for (const 文本 of 文本们) {
      const 卡 = 应用魂环(新建('div', 'dl-route-box'), 命中 ? 取魂环类(文本, 'dl-ring-black') : 'dl-ring-white');
      卡.dataset.routeHit = 命中 ? 'true' : 'false';
      卡.appendChild(生成字段组(文本, false));
